                'enableMouseUp' : true,
                'enableMouseOver' : true,
                'enableMouseOut' : true,
                'enableMouseLeave' : true,
                'enableLassoStart' : true,
                'enableLassoMove' : true,
                'enableLassoEnd' : true,
                'enableContextMenu' : true
