        SEL_CLASSDATAPOINT = '.' + CLASSDATAPOINT,
        CLASSMORPHABLEDATAPOINT = Constants.CSS.CLASS.MORPHABLEDATAPOINT,
        MORPHABLEAREABG = Constants.CSS.CLASS.MORPHABLEAREABG;
