    /**
     * get/set your event dispatch if you support event
     */
    Area.prototype.dispatch = function(_){
      if(!arguments.length){
        return this._eDispatch;}
      this._eDispatch = _;
      return this;
    };
    /**
     * set/get data, for some modules like Title, it doesn't need data
     */
    Area.prototype.data = function(value){
      if (!arguments.length){
        return this._area_data;
      }
      this._area_isDatasetChanged = true;
      this._area_isDataSchemaChanged = false;
      if (! dataUtil().hasSameSchema(this._area_data, value)){
        this._area_isDataSchemaChanged = true;
      }
      this._area_bDataUpdated = true;
      this._area_data = value;
      var obj = MNDHandler(this._area_data);
      this._valueAxis1.data = obj["MG1"];
      
      //[04-Mar-2013 Nick] Testify whether defaultselection
      var dataInfo;
      if(this._valueAxis1.data.length !== 0){
        dataInfo = this._valueAxis1.data[0][0];
      }
      if(dataInfo.info &&  dataInfo.info.defaultSelection){
        this._area_hasDefaultSelection = true;
      }else{
        this._area_hasDefaultSelection = false;
      }
      
      this._areafn_resetDataRange();
      
      //alex su
      this._area_tooltipData = TooltipDataHandler.dataTransform(obj);
      this._areafn_computeScales();
      this._areafn_createColorPalette();

      return this;
    };
    
