    var isOverBound = function (rect) {
        var boundRect = null, isOver = false;
        
        //BITSDC1-6855
        //CVOM creates v-m-tooltip-container div for viz chart 
        //so that Lumira can look up the div and apply the reverse scaling factor.        
        if (this._parentNodeRect) {
            boundRect = this._parentNodeRect;
        } else {
            boundRect = this._div.node().parentNode.parentNode.getBoundingClientRect();
        }

        if (rect.isVertical) {
            if ((rect.clientRect.top < boundRect.top) || (rect.clientRect.bottom >  boundRect.bottom)) {
                isOver = true;
            }
        } else {
            if ((rect.clientRect.left < boundRect.left || rect.clientRect.right > boundRect.right)) {
                isOver = true;
            }
        }
        return isOver;
    };

    Tooltip.prototype.moveTo = function(moveInfo) {
        if (!this._div || this._isAnchored) {
            return;
        }

        var rect = {
            clientRect : {},
            isVertical : true
        };

        var offset = 0;
        if (moveInfo.direction === 'Y') {
            offset = parseInt(this._div.style("top")) + moveInfo.offset.y;
            this._div.style("top", offset + "px");
        } else if (moveInfo.direction === 'X') {
            offset = parseInt(this._div.style("left")) + moveInfo.offset.x;
            rect.isVertical = false;
            this._div.style("left", offset + "px");
        }

        rect.clientRect = this._div.node().getBoundingClientRect();
        if (isOverBound.call(this, rect)) {
            this._div.style("visibility", "hidden");
        } else {
            this._div.style("visibility", "visible");
        }
    };

    Tooltip.prototype._updateTooltipStyle = function() {     
        if(this._properties.background) {
          if (this._properties.background.color) {
            this._defaultToolTipColors.backgroundColor = this._properties.background.color;
          }        
          if (this._properties.background.borderColor) {
              this._defaultToolTipColors.border = this._properties.background.borderColor;
          }
        }        

        if (this._properties.bodyDimensionLabel && this._properties.bodyDimensionLabel.color) {
            this._defaultToolTipColors.dimensionName = this._properties.bodyDimensionLabel.color;
        }

        if (this._properties.bodyDimensionValue && this._properties.bodyDimensionValue.color) {
            this._defaultToolTipColors.dimensionValue = this._properties.bodyDimensionValue.color;
        }
        
        if (this._properties.bodyMeasureLabel && this._properties.bodyMeasureLabel.color) {
            this._defaultToolTipColors.measureName = this._properties.bodyMeasureLabel.color;
        }

        if (this._properties.bodyMeasureValue && this._properties.bodyMeasureValue.color) {
            this._defaultToolTipColors.measureValue = this._properties.bodyMeasureValue.color;
        }

        if (this._properties.bodyLabel && this._properties.bodyLabel.color) {
            this._defaultToolTipColors.dimensionName = this._properties.bodyLabel.color;
            this._defaultToolTipColors.measureName = this._properties.bodyLabel.color;
        }

        if (this._properties.bodyValue && this._properties.bodyValue.color) {
            this._defaultToolTipColors.dimensionValue = this._properties.bodyValue.color;
            this._defaultToolTipColors.measureValue = this._properties.bodyValue.color;
        }

        if (this._properties.separationLine && this._properties.separationLine.borderBottomColor) {
            this._defaultToolTipColors.separationLineSingleColor = this._properties.separationLine.borderBottomColor;
        }

        if (this._properties.footerLabel && this._properties.footerLabel.color) {
            this._defaultToolTipColors.footerLabelColor = this._properties.footerLabel.color;
        }

        if (this._properties.closeButton){
            if (this._properties.closeButton.backgroundColor){
                this._defaultToolTipColors.closeButtonBackground = this._properties.closeButton.backgroundColor;
            }
            if (this._properties.closeButton.borderColor){
                this._defaultToolTipColors.closeButtonBorderColor = this._properties.closeButton.borderColor;
            }
        }
    };

    OO.extend(Tooltip, Base);

    return Tooltip;
