      modules[axis].labelAngle(labelAngle).tickAngle(tickAngle);

      vector = new Vector3D(point.x - origin.x, point.y - origin.y, point.z
          - origin.z);
      selections[axis].attr('transform', 'translate(' + origin.x + ' '
          + origin.y + ')');
