/*
 * this class is used to replace rotate module.
 * it will be referenced by 3D series charts in their chart manifests to overwrite
 * pan series handler of Interaction to implement rotation feature.
 * NOTE: as rotate.js, this class doesn't support mobile device yet.
 */
define('sap/viz/chart/elements/utils/RotateHandler',[], function(){
    /**
     * 
     * @param {type} module the module implementing rotate method, currently it's one of xycontainer & xyzcontainer
     * @returns {undefined}
     */
    var RotateHandler = function() {
        this._xAngle = undefined;
        this._yAngle = undefined;
        this._oldX = undefined;
        this._oldY = undefined;
        this._module = undefined;
    };
    
    function getCurrentEvent() {
        if (d3.event) {
            return d3.event;
        } else {
            return window.event;
        }
    }    
    
    var rhp = RotateHandler.prototype;
    
    rhp.rotateStart = function(event, module) {
        var angle = module.rotate();
        this._xAngle = angle.xAngle;
        this._yAngle = angle.yAngle;
        this._module = module;
        
        var rawEvent = getCurrentEvent();
        this._oldX = rawEvent.layerX;
        this._oldY = rawEvent.layerY;
    };
    
    rhp.rotateMove = function(event) {
      if(!this._module){
        return;
      }
      
        var rawEvent = getCurrentEvent(),
            x = rawEvent.layerX,
            y = rawEvent.layerY;
        //y angle
        this._yAngle += (this._oldX - x) / 2;
        if (this._yAngle > 180) {
            this._yAngle -= 360;
        } else if (this._yAngle < -180) {
            this._yAngle += 360;
        }
        //x angle
        this._xAngle += (y - this._oldY) / 2;
        if (this._xAngle > 90) {
            this._xAngle = 90;
        } else if (this._xAngle < -90) {
            this._xAngle = -90;
        }
        
        this._oldX = x;
        this._oldY = y;
        
        this._module.rotate({
            xAngle: this._xAngle,
            yAngle: this._yAngle
        });
        

       //stop event, as if we bubble this event. It will be caught by framework. It will find the UI component and fire error
       //message that the parent node is not exist.
       rawEvent.stopPropagation();
       rawEvent.preventDefault();    
    };
    
    rhp.rotateEnd = function(event) {
      if(!this._module){
        return;
      }
        if (this._module.rotateEnd) {
            this._module.rotateEnd();
        }
    };
    
    rhp.destroy = function() {
        this._module = null;
    };
    
    return RotateHandler;
});

