  BaseLine.prototype.clear = function (gray) {
  };

  BaseLine.prototype.highlight = function (elements, hovered) {
    if (!TypeUtils.isArray(elements)) {
      elements = [ elements ];
    }
    var i;
    if(!hovered){
      for (i=0; i<elements.length; i++)
      {
        var marker = elements[i];
        if(!this._linefn_processOneAxisSelect( this._valueAxis1, marker )){
          this._linefn_processOneAxisSelect( this._valueAxis2, marker);
        }
      }
    }else{
      d3.selectAll(elements).classed(CLASSMARKERSELECTED,false).classed(CLASSMARKERHOVER,true);
      DrawUtil.nodesHighlight(elements, {factor : 0.7, constant : 0}, this._line_effectManager, hovered);
      if(!this._props.marker.visible){
        for (i=0; i<elements.length; i++)
        {
          elements[i].setAttribute('fill-opacity', 1 );
          elements[i].setAttribute('stroke-opacity', 1 );
        }
      }
    }

    if (!hovered && this._props.marker.visible){
      this._line_svgMarkersGroup.selectAll("g." +  PREFIXAXIS1).selectAll("g.v-marker")
      .selectAll("."+ CLASSMARKERSELECTED).attr("fill-opacity", 1).classed(CLASSMARKERDEFAULT, false);
      this._line_svgMarkersGroup.selectAll("g." +  PREFIXAXIS2).selectAll("g.v-marker")
      .selectAll("."+ CLASSMARKERSELECTED).attr("fill-opacity", 1).classed(CLASSMARKERDEFAULT, false);
    }
    
    if(this._line_hasDefaultSelection){
      defaultSelUtil.clearSelectionInfo(this._d3root, true, elements);
    }
  };

  BaseLine.prototype.unhighlight = function (elements, selected, normalMode) {
    if (!TypeUtils.isArray(elements)) {
      elements = [ elements ];
    }
    var i;
    if(!selected && !normalMode){
      this._line_selectedMarkerNum -= elements.length;
      for (i=0; i<elements.length; i++)
      {
        var marker = elements[i];

        if(!this._linefn_processOneAxisDeselect( this._valueAxis1, marker, normalMode)){
          this._linefn_processOneAxisDeselect( this._valueAxis2, marker, normalMode);
        }
      }
    }else{
      DrawUtil.nodesUnhighlight(elements,selected, normalMode);
      if(selected){
        d3.selectAll(elements).classed(CLASSMARKERSELECTED,true).classed(CLASSMARKERHOVER,false);
      }else{
        d3.selectAll(elements).classed(CLASSMARKERSELECTED,false).classed(CLASSMARKERHOVER,false).classed(CLASSMARKERDEFAULT,true);
        if(!this._props.marker.visible){
          for(i=0; i<elements.length;i++){
            elements[i].setAttribute('fill-opacity', 0 );
            elements[i].setAttribute('stroke-opacity', 0 );
          }
        }
      }
    }

    if(this._line_hasDefaultSelection){
      defaultSelUtil.clearSelectionInfo(this._d3root, false, elements);
    }
  };

  BaseLine.prototype.globalDOMDestroy = function(_){
    var i=0;
    if(_){
      _.remove(); //delete DOM
      for(i=0;i<_.length;i++){  // set null
        _[i] = null;
      }
      _ = null;
    }
  };

  BaseLine.prototype.destroy = function() {
    var i =0;
    var j =0;
    if(this._line_tooltipData){
      for(i=0;i<this._line_tooltipData.length;i++){
        this._line_tooltipData[i] = null;
      }
      this._line_tooltipData = null;
    }
    //don't simply set m_scale to null
    //we need clear the internal cached index and range

    if(this._valueAxis1){
      if(this._valueAxis1.scale){
        this._valueAxis1.scale.domain([0,1]).range([0,1]);
      }
      if(this._valueAxis1.data){
        for(i=0; i<this._valueAxis1.data.length;i++){
          this._valueAxis1.data[i] = null;
        }
        this._valueAxis1.data = null;
      }
      if(this._valueAxis1.selectedMarkers){
        for(i=0; i<this._valueAxis1.selectedMarkers.length;i++){
          this._valueAxis1.selectedMarkers[i] = null;
        }
        this._valueAxis1.selectedMarkers = null;
      }
      if(this._valueAxis1.markers){
        for(i=0; i<this._valueAxis1.markers.length;i++){
          for(j=0; j<this._valueAxis1.markers[i].length;j++){
            if (this._valueAxis1.markers[i] && this._valueAxis1.markers[i][j] && this._valueAxis1.markers[i][j].remove) {
              this._valueAxis1.markers[i][j].remove();
            }
            this._valueAxis1.markers[i][j] = null;
          }
          this._valueAxis1.markers[i] = null;
        }
        this._valueAxis1.markers = null;
      }
      this._valueAxis1 = null;
    }
    
    if(this._valueAxis2){
      if(this._valueAxis2.scale){
        this._valueAxis2.scale.domain([0,1]).range([0,1]);
      }
      if(this._valueAxis2.data){
        for(i=0; i<this._valueAxis2.data.length;i++){
          this._valueAxis2.data[i] = null;
        }
        this._valueAxis2.data = null;
      }
      if(this._valueAxis2.selectedMarkers){
        for(i=0; i<this._valueAxis2.selectedMarkers.length;i++){
          this._valueAxis2.selectedMarkers[i] = null;
        }
        this._valueAxis2.selectedMarkers = null;
      }
      if(this._valueAxis2.markers){
        for(i=0; i<this._valueAxis2.markers.length;i++){
          for(j=0; j<this._valueAxis2.markers[i].length;j++){
            if (this._valueAxis2.markers[i] && this._valueAxis2.markers[i][j] && this._valueAxis2.markers[i][j].remove) {
              this._valueAxis2.markers[i][j].remove();
            }
            this._valueAxis2.markers[i][j] = null;
          }
          this._valueAxis2.markers[i] = null;
        }
        this._valueAxis2.markers = null;
      }
      this._valueAxis2 = null;
    }

    if(this._categoryScale){
      this._categoryScale.domain([0,1]).range([0,1]);
      this._categoryScale = null;
    }

    //delete DOM and set null
    if(this._d3root){
      this._d3root.selectAll('.'+ CLASSDATAPOINT).remove(); 
    }
    if(this._line_svgLinesGroup){
      this.globalDOMDestroy(this._line_svgLinesGroup);
      this._line_svgLinesGroup = null;
    }
    if(this._line_svgLightLinesGroup){
      this.globalDOMDestroy(this._line_svgLightLinesGroup);
      this._line_svgLightLinesGroup = null;
    }
    if(this._line_svgMarkersGroup){
      this.globalDOMDestroy(this._line_svgMarkersGroup);
      this._line_svgMarkersGroup = null;
    }
    if(this._datashapesgroup){
      this.globalDOMDestroy(this._datashapesgroup);
      this._datashapesgroup = null;
    }

    if(this._line_clipRect){
      this.globalDOMDestroy(this._line_clipRect);
      this._line_clipRect = null;
    }
    if(this._d3root){
      this.globalDOMDestroy(this._d3root);
      this._d3root = null;
    }
    
    //set null
    this._line_animation_clipPath = null;
    this._line_animation_clipRect = null;
    this._line_data = null;
    this._raw_data = null;

    if(this._line_effectManager && this._line_effectManager.destroy){
      this._line_effectManager.destroy();
    }
    if(this._line_styleManager && this._line_styleManager.destroy){
      this._line_styleManager.destroy();
    }

    this._eDispatch = null;
    this._line_colorPalette = null;
    this._line_randomSuffix = null;
    this._line_tooltipDataHandler = null;
    this._props = null;

    this._line_effectManager = null;
    this._line_styleManager = null;
  };

  //@Alex Su, judge whether we should enable animation
  BaseLine.prototype._linefn_enableAnimation = function(){
    var hasAnmation = false;
    if(this._line_isDataLoading){
      hasAnmation = this._props.animation.dataLoading;
    }else if(this._line_isDatasetChanged){
      hasAnmation = this._props.animation.dataUpdating;
    }else if(this._line_isSizeChanged){
      hasAnmation = this._props.animation.resizing;
    }
    return hasAnmation;
  };
  
  BaseLine.prototype.setRawData = function(data){
    this._raw_data = data;
  };

  BaseLine.prototype._linefn_createColorPalette = function() {
    this._line_colorPalette = [];
    var i = 0, j = 0;
    if(this._valueAxis2.data && this._valueAxis2.data.length > 0){
      this._valueAxis1.colorPalette = this._props.primaryValuesColorPalette;
    } else {
      this._valueAxis1.colorPalette = this._props.colorPalette;
    }

    this._valueAxis2.colorPalette = this._props.secondaryValuesColorPalette;
    
    if (this._line_hasMND && this._line_bMNDOnColor && this._line_bMNDInner) {
      var dva1 = this._line_data.getMeasureValuesGroupDataByIdx(0);
      var dva2 = this._line_data.getMeasureValuesGroupDataByIdx(1);
      var mg1mNum=0, mg2mNum=0, mNum=0, colorAxisDataNum=0;
      if (dva1 && dva1.values.length>0) { 
        mg1mNum = dva1.values.length;
        colorAxisDataNum = dva1.values[0].rows.length;
      }
      if (dva2 && dva2.values.length>0) {
        mg2mNum = dva2.values.length;
        colorAxisDataNum = dva2.values[0].rows.length;
      }

      for (i=0; i<colorAxisDataNum; i++) {
        for (j=0; j<mg1mNum; j++) {
          this._line_colorPalette.push(this._valueAxis1.colorPalette[(i*mg1mNum+j) % this._valueAxis1.colorPalette.length]);
        }
        for (j=0; j<mg2mNum; j++){
          this._line_colorPalette.push(this._valueAxis2.colorPalette[(i*mg2mNum+j) % this._valueAxis2.colorPalette.length]);
        }
      }
    } else {
      for(i = 0; i < this._valueAxis1.data.length; ++i){
        this._line_colorPalette.push(this._valueAxis1.colorPalette[i % this._valueAxis1.colorPalette.length]);
      }
      if(this._valueAxis2.data && this._valueAxis2.data.length > 0)
      {
        for(i = 0; i < this._valueAxis2.data.length; ++i){
          this._line_colorPalette.push(this._valueAxis2.colorPalette[i % this._valueAxis2.colorPalette.length]);
        }
      }
    }
  };

  BaseLine.prototype._linefn_resetDataRange = function(){
    this._valueAxis1.highLines = [];
    this._valueAxis2.highLines = [];
    if (!this._valueAxis1.manualRange) {
      this._valueAxis1.topValue = null;
      this._valueAxis1.bottomValue = null;
    }
    if (!this._valueAxis2.manualRange) {
      this._valueAxis2.topValue = null;
      this._valueAxis2.bottomValue = null;
    }
    this._valueAxis1.scale = d3.scale.linear();
    this._valueAxis2.scale = d3.scale.linear();
  };

