define('sap/viz/modules/manifests/PieWithDepth',['sap/viz/modules/manifests/Module',
  'sap/viz/modules/Constants',
  'sap/viz/modules/piewithdepth'],
function Setup(Manifest, Constants, fn) {
  var module = {
    'id' : 'sap.viz.modules.piewithdepth',
    'name' : 'piewithdepth',
    'type' : Constants.Type.Chart,
    'properties' : {
      'colorPalette' : {
        'name' : 'colorPalette',
        'supportedValueType' : 'StringArray',
        'defaultValue' : Constants.COLOR.SAPColorSingleAxis,
        'description' : 'Set the color palette for sectors.',
        'example': "<a href='"+Constants.DocExample.SnippetUrl+"4449' target='_blank'>"+Constants.DocExample.TryThisValue+"</a>"
      },
      'isDonut' : {
        'name' : 'isDonut',
        'supportedValueType' : 'Boolean',
        'defaultValue' : false,
        'description' : "Set the chart to display as a donut or a pie. If this value is set to 'true', the chart displays as a donut. If this value is set to 'false', the chart displays as a pie."
      },
      'drawingEffect':{
        'name' : 'drawingEffect',
          'description' : 'Set the drawing effect for the 3D elements.',
        'supportedValueType' : 'String',
          'supportedValues' : [ 'normal', 'glossy' ],
          'defaultValue' : 'normal',
          'isExported' : true,
      }
    },
    'events' : {
      'initialized' : Constants.Event.Initialized.desc,
      'selectData' : Constants.Event.SelectData.desc,
      'deselectData' : Constants.Event.DeSelectData.desc
    },
    'feeds' : {
      id : "pie",
      configure : null
    },
    fn : fn
  };
  var manifests = {
    viz: [],
    module: [module],
    feeds: []
  }
  return manifests;
});
define('sap/viz/manifests/pie/PieWithDepthChart',['sap/viz/manifests/Viz',
  'sap/viz/modules/manifests/RootContainer',
  'sap/viz/manifests/pie/PieChart',
  'sap/viz/modules/manifests/PieWithDepth',
  'sap/viz/modules/manifests/DataLabel',
  'sap/viz/chart/elements/manifests/controller/Interaction',
  'sap/viz/chart/elements/utils/RotateHandler',
  'sap/viz/chart/elements/behaviors/InteractionHelper',
  'sap/viz/util/BoundingBox'
  /*'sap/viz/modules/manifests/controller/Rotate'*/],
function Setup(Manifest, RootContainer, PieChart, PieWithDepth, DataLabel, Interaction, RotateHandler, iHelper, BoundingBox) {
  var rotateHandler = new RotateHandler();
  var isEqual = function(dp1, dp2) {
    return d3.select(dp1).datum().index === d3.select(dp2).datum().index;
  };
  var lastSelected;
  var chart = {
    id : 'viz/pie_with_depth',
    name : 'IDS_PIEWITHDEPTHCHART',
    base : "riv/base/single",
    isBuiltIn: true,
    legacyDataAdapter: true,
    dataModel: 'sap.viz.api.data.CrosstableDataset',
    modules : {
      root : {
        configure : {
          propertyCategory : 'general',
          propertiesOverride : {
            layout : {
              hideAxisTitleFirst : {
                isExported : false
              }
            }
          }     
        },

        modules : {


          legends : {
            modules : {
              legend : {
                data : { aa : [ 1 ] }
              }
            }
          },
          
          tooltip : {
            id : 'sap.viz.chart.elements.Tooltip',
            configure : {
              propertyCategory : 'tooltip',
              properties : { 
                  chartType : 'pie_with_depth', 
                  orientation : 'left' 
              }
            }
          },
          
          interaction : {
            id : 'sap.viz.modules.controller.interaction',
            configure : {
              clientID : 'main',
              propertyCategory : 'interaction',
              properties : {
                selectability: {
                    mode: 'inclusive',
                  lassoWithCtrlKey: true
                },
                preserveSelectionWhenDragging: true,
                dataPointsCacheable: false,
                holdSelection: false,
                extensionPoints: {
                  isEqual: isEqual
                },
                'handlers': [{
                    'triggerKey': 'pan_start_on_eventLayer',
                    'fn': function(event) {
                        var bbox = iHelper.getBoundingBox( this._rootNode.select(".v-m-main > .v-bound").node() );
                        if (!BoundingBox.contains(bbox, event.data.point)) {
                          return;
                        }
                        lastSelected = [].concat(this._lastSelected);
                        this.runDecoration('hideDetail', 'infoMode');
                        this.runDecoration('hideDetail', 'actionMode');
                        var rotateContainer = this._selb_plots["main"];
                        rotateHandler.rotateStart(event, rotateContainer);
                    }
                }, {
                    'triggerKey': 'pan_move_on_eventLayer',
                    'fn': function(event) {
                        var bbox = iHelper.getBoundingBox( this._rootNode.select(".v-m-main > .v-bound").node() );
                        if (!BoundingBox.contains(bbox, event.data.point)) {
                          return;
                        }
                        rotateHandler.rotateMove(event);
                    }
                }, {
                    'triggerKey': 'pan_end_on_eventLayer',
                    'fn': function(event) {
                        var bbox = iHelper.getBoundingBox( this._rootNode.select(".v-m-main > .v-bound").node() );
                        if (!BoundingBox.contains(bbox, event.data.point)) {
                          return;
                        }
                        rotateHandler.rotateEnd(event);
                        //because 3D Pie removes all data points and add new ones,
                        //we need to find the new counterparts for selections
                        if (lastSelected.length) {
                            var plotNode = iHelper.findPlotNodeContainingNode(event.data.target);
                            if (plotNode) {
                                var dps = plotNode.querySelectorAll(".v-datapoint");
                                var sels = [], notSels = [];
                                for (var i = -1; ++i < dps.length; ) {
                                    for (var j = -1; ++j < lastSelected.length; ) {
                                        if (isEqual(dps[i], lastSelected[j])) {
                                            sels.push(dps[i]);
                                            break;
                                        }
                                    }
                                    if (j >= lastSelected.length) {
                                        notSels.push(dps[i]);
                                    }
                                }
                                this._lastSelected = sels;
                                this.runDecoration('highlightBySelecting', this._lastSelected);
                                this.runDecoration('unhighlight', notSels, false, false);
                            }
                        }
                    }
                }]                    
              }
            }
          },
          
          main : {
            id : 'sap.viz.modules.xycontainer',
            configure : {
              propertyCategory : 'xyContainer',
              properties : {
                yAngle : 0
              },
              propertiesOverride : {
                yAngle : {
                  isExported : true
                }
              }
            },
            modules : {
              plot : {
                id : 'sap.viz.modules.piewithdepth',
                configure : {
                  description : 'Settings for the appearance of the chart and plot areas, as well as other chart options',
                  propertyCategory : 'plotArea'
                }
              }
            }
          }
        }
      }
    },
    dependencies : {
      attributes : [ {
        targetModule : 'root.legends.legend',
        target : 'colorPalette',
        sourceModule : 'root.main.plot',
        source : 'colorPalette'
      }],
      events : [ 
      {
          targetModule : 'root.interaction',
          listener : 'initialize',
          sourceModule : 'root.main.plot',
          type : 'initialized.interaction'
      }/*, {
          targetModule : 'root.rotate',
          listener : 'registerEvent',
          sourceModule : 'root.main.plot',
          type : 'initialized.rotate'
      }*/]
    }
  };

    var manifests = {
      viz: [chart].concat(PieChart.viz),
      module: [].concat(PieChart.module, RootContainer.module, PieWithDepth.module, DataLabel.module, Interaction.module/*, Rotate.module*/),
      feeds: [].concat(PieChart.feeds, RootContainer.feeds, PieWithDepth.feeds, DataLabel.feeds, Interaction.feeds/*, Rotate.feeds*/)
    };
    return manifests;
});

