        links = that._graph.links,
        charge = that._charge,
        distances = that._distances,
        strengths = that._strengths,
        charges = that._charges,
        gravity = that._gravity,
        friction = that._friction,
        n = nodes.length,
        m = links.length,
        w = that._width,
        h = that._height,
        r = that._radius,
        q,
