define('sap/viz/modules/tagcloud/rowLayout',['sap/viz/util/TextUtils','sap/viz/util/NumberUtils'],
function Setup(TextRuler, NumberUtils) {
  var rowLayout = function() {
    var width = 300, height = 300, chartData = [], font = '';

    var textDirection = 'Mixed';
    var numOfTruncation = 10;

    var row = function() {

    };

    row.numOfTruncation = function(_){
      if (!arguments.length) {
        return numOfTruncation;  
      }
        
      numOfTruncation = _;
      return row;
    };
    
    row.textDirection = function(_) {
      if (!arguments.length) {
        return textDirection;  
      }
        
      textDirection = _;
      return row;
    };
    
    row.width = function(_) {
      if (!arguments.length){
        return width;
      }
      width = _;
      return row;
    };

    row.height = function(_) {
      if (!arguments.length){
        return height;
      }
      height = _;
      return row;
    };

    row.data = function(_) {
      if (!arguments.length){
        return chartData;
      }
      chartData = _;
      return row;
    };

    row.font = function(_) {
      if (!arguments.length){
        return font;
      }
      font = _;
      return row;
    };

    row.layout = function() {
      _layout();
      return row;
    };

    var _layout = function() {
      var tagArr = chartData;
      var d, textSize, i, len;
      var startX = 0;
      var maxRowHeight = 0, startY = 0, newLineIndex = 0;
      for (i = 0, len = tagArr.length; i < len; i++) {
        var ellipsisFlag = false;

        d = tagArr[i];
        d.word.val = d.originalWord;
        
        //Rest x and y
        d.x = undefined;
        d.y = undefined;
        
        var ellipsisLength = TextRuler.fastMeasure('MMM...', d.fontSize + 'px' , 'normal' , font).width;
        if ( startY <= height) {
          textSize = TextRuler.fastMeasure(tagArr[i].word.val+'i', tagArr[i].fontSize+'px', 'normal', font);
          d.width = textSize.width;
          d.height = textSize.height;
        } else {
          d.width = 0;
          d.height = 0;
          continue;
        }
        if((d.height > height) || (NumberUtils.isNoValue(tagArr[i].fontSize))){
          continue;
        }
        if(i >= numOfTruncation && d.width > width){
          continue;
        }
        if(i < numOfTruncation && ellipsisLength > width){
          continue;
        }
        
        if (startX + d.width > width) {
          if(d.width <= width){
            // New Row
            startX = 0;
            _adjustLastLineTagPosition(newLineIndex, i, startY + maxRowHeight);            
            newLineIndex = i;
            startY = startY + maxRowHeight;
            maxRowHeight = tagArr[i].height;
          }else{
            if(ellipsisLength <= width - startX){
              d.width = width - startX;
            }else{
              // New Row
              startX = 0;
              _adjustLastLineTagPosition(newLineIndex, i, startY + maxRowHeight);            
              newLineIndex = i;
              startY = startY + maxRowHeight;
              maxRowHeight = tagArr[i].height;

              d.width = width;
            }
            ellipsisFlag = true;         
          }
        }

        if(d.height > maxRowHeight){
          maxRowHeight = d.height;
        }
        d.x = startX;
        d.y = startY;
        startX = startX + d.width;

        if(ellipsisFlag){
          d.word.val = TextRuler.ellipsis(d.originalWord, null, d.width,  'font-weight:' + 'normal' + ';font-family:' + font + ';font-size:' + d.fontSize + 'px');  
        }
        d.rotate = undefined;
      }
      _adjustLastLineTagPosition(newLineIndex, i, startY + maxRowHeight);
    };
    
    /*
     * Set last line tag position.
     */
    var _adjustLastLineTagPosition = function(startIndex, endIndex, newYPosition){
      var dArr;
      for(var j = startIndex; j < endIndex; j++){
        dArr = chartData[j];
        if(dArr.y !== undefined){
          dArr.y = newYPosition;
        }
      }
    };
    return row;
  };
  return rowLayout;
});

